<!doctype html><html><head><meta charset="utf-8"><title>Quotation {{ $quotation->quotation_no }}</title><style>body{font-family:Arial,sans-serif;font-size:12px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #333;padding:6px}.num{text-align:right}</style></head><body><h1>Quotation</h1><p><b>No:</b> {{ $quotation->quotation_no }} · <b>Date:</b> {{ $quotation->quotation_date->format('d-m-Y') }} @include('company.components.nepali-date-display',['adDate'=>$quotation->quotation_date]) · <b>Customer:</b> {{ $quotation->customer?->name }} · <b>Status:</b> {{ ucfirst($quotation->status) }}</p><table><thead><tr><th>#</th><th>Item</th><th class="num">Qty</th><th class="num">Unit Price</th><th class="num">VAT</th><th class="num">Total</th></tr></thead><tbody>@foreach($quotation->items as $item)<tr><td>{{ $loop->iteration }}</td><td>{{ $item->product?->name ?? $item->service?->name }}</td><td class="num">{{ $item->quantity }}</td><td class="num">{{ number_format((float)$item->unit_price,2) }}</td><td class="num">{{ number_format((float)$item->vat_amount,2) }}</td><td class="num">{{ number_format((float)$item->total_price,2) }}</td></tr>@endforeach</tbody><tfoot><tr><th colspan="5">Grand Total</th><th class="num">{{ number_format((float)$quotation->grand_total,2) }}</th></tr></tfoot></table><p>{{ $quotation->note }}</p><script>window.print()</script></body></html>
